        """Reflect by grid boundary"""
        if dx < 0:
            return x - 1, y + dy, 1, dy  # Hit left wall
        elif dx > 0:
            return x + 1, y + dy, -1, dy  # Hit right wall
        elif dy < 0:
            return x + dx, y - 1, dx, 1   # Hit top wall
        elif dy > 0:
            return x + dx, y + 1, dx, -1  # Hit bottom wall
        return x, y, dx, dy

    def check_blocked_and_compute_next(curr_x, curr_y, dx, dy, n, m, blocked):
        """Move from current cell, check for blocked/boundary, and compute next state"""
        x, y = curr_x, curr_y

        # Move in current direction until we hit boundary or blocked cell
        while True:
            next_x, next_y = x + dx, y + dy

            # Check if next position is out of bounds
            if next_x < 1 or next_x > n or next_y < 1 or next_y > m:
                # Hit wall, reflect
                if dx < 0:
                    dx = 1
                elif dx > 0:
                    dx = -1
                elif dy < 0:
                    dy = 1
                elif dy > 0:
                    dy = -1
                x, y = next_x, next_y
                break

            # Check if next position is blocked
            if (next_x, next_y) in blocked:
                # Hit blocked cell, reflect
                if dx < 0:
                    dx = 1
                elif dx > 0:
                    dx = -1
                elif dy < 0:
                    dy = 1
                elif dy > 0:
                    dy = -1
                x, y = next_x, next_y
                break

            x, y = next_x, next_y

        return x, y, dx, dy

    # Simulate the path
    x, y = xs, ys
    d_x, d_y = dx, dy

    while True:
        state = (x, y, d_x, d_y)
        if state in visited:
            # Cycle detected
            break
        visited.add(state)

        # Add current cell to path
        path.append((x, y))

        # Move to next cell
        x, y, d_x, d_y = check_blocked_and_compute_next(x, y, d_x, d_y, n, m, blocked)

    # Remove blocked cells from path and count unique empty cells
    empty_cells = set()
    for px, py in path:
        if (px, py) not in blocked:
            empty_cells.add((px, py))

    return f"{len(empty_cells)}\n"


