def is_geometric_progression(seq):
    n = len(seq)
    if n <= 1:
        return True

    # Check for all zeros
    if all(x == 0 for x in seq):
        return True

    # Find common ratio from first two elements
    a = seq[0]
    b = seq[1]

    # Handle first pair
    if a == 0:
        if b == 0:
            # First two are zero, check rest
            ratio = None
            for i in range(2, n):
                if seq[i] != 0:
                    # Can't have non-zero after zero with ratio 0 unless we handle carefully
                    continue
            return True
        elif b == 0:
            # a != 0, b == 0 means ratio is 0, so all subsequent must be 0
            ratio = 0
        else:
            ratio = b / a
    elif b == 0:
        ratio = 0
    else:
        ratio = b / a

    # Verify the ratio for all remaining elements
    for i in range(2, n):
        expected = seq[i - 1] * ratio
        if abs(seq[i] - expected) > 1e-9:  # Use tolerance for floating point
            return False

    return True


