import sys
from math import gcd
from functools import reduce
from typing import List, Set, Dict

def get_divisors(n: int) -> List[int]:
    """Get all divisors of n greater than 1, sorted ascending."""
    divisors = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i > 1:
                divisors.append(i)
            if i * i != n and n // i > 1:
                divisors.append(n // i)
        i += 1
    return sorted(divisors)

def prime_factors(n: int) -> Dict[int, int]:
    """Return prime factors of n with their exponents."""
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def lcm(a: int, b: int) -> int:
    """Return least common multiple of a and b."""
    return (a * b) // gcd(a, b)

def can_place_adjacent(nums: List[int]) -> bool:
    """Check if any adjacent pair in the circular list are coprime."""
    n = len(nums)
    for i in range(n):
        if gcd(nums[i], nums[(i + 1) % n]) == 1:
            return True
    return False

def build_factor_string(n: int) -> str:
    """Create a string representation of n based on its prime factors."""
    factors = prime_factors(n)
    result = []
    for p in sorted(factors.keys()):
        exp = factors[p]
        for _ in range(exp):
            result.append(p)
    return ''.join(str(x) for x in result)

def solve(n: int) -> tuple:
    """Solve for a single composite number n."""
    if n < 4 or n > 10**9:
        return [], 0

    divisors = get_divisors(n)

    if len(divisors) <= 1:
        return divisors, 0

    # If prime power, all divisors share the same prime factor
    factors = prime_factors(n)
    if len(factors) <= 1:
        return divisors, 0

    # Try to build a valid ordering where no adjacent are coprime
    # Use a greedy approach with backtracking

    # Sort by number of distinct prime factors (descending)
    def count_factors(x):
        return len(set(prime_factors(x).keys()))

    sorted_divs = sorted(divisors, key=count_factors, reverse=True)

    # Try to arrange with backtracking (since total divisors ≤ 2e5, but actual per test is small)
    used = [False] * len(divisors)

    def backtrack(path: List[int]):
        if len(path) == len(divisors):
            return path

        last = path[-1] if path else 0
        # Try remaining divisors
        for i in range(len(sorted_divs)):
            if not used[i]:
                candidate = sorted_divs[i]
                if gcd(last, candidate) > 1:  # Can be placed next to last
                    used[i] = True
                    path.append(candidate)
                    result = backtrack(path)
                    if result is not None:
                        return result
                    path.pop()
                    used[i] = False
        return None

    # With greedy that prioritizes factors
    def greedy_build():
        # Start with divisor that has most prime factors
        if not divisors:
            return []

        start_div = max(divisors, key=lambda x: len(set(prime_factors(x).keys())))
        used = [False] * len(divisors)
