                    if g > 1 or best_idx == -1:
                        if g > best_gcd:
                            best = val
                            best_idx = i
                            best_gcd = g
                        elif g == best_gcd and best_gcd > 1:
                            # Tie-breaker: prefer more factors
                            if len(set(prime_factors(val).keys())) > len(set(prime_factors(best).keys())):
                                best = val
                                best_idx = i

            if best_idx != -1:
