def solution(input_string):
    lines = input_string.strip().split('\n')
    if not lines:
        return ''

    q = int(lines[0])
    results = []

    idx = 1
    for _ in range(q):
        n = int(lines[idx])
        idx += 1
        a = list(map(int, lines[idx].split()))
        idx += 1

        if n == 0:
            results.append('0')
            continue

        unique = sorted(set(a))
        first_pos = {}
        last_pos = {}

        for i, x in enumerate(a):
            if x not in first_pos:
                first_pos[x] = i
            last_pos[x] = i

        m = len(unique)

        if m == 0:
            results.append('0')
            continue

        # Use DP with memoization
        # dp[i] = length of longest valid chain starting from unique[i]
        dp = {}

        def compute(i):
            if i == m - 1:
                return 1
            if i in dp:
                return dp[i]

            result = 1
            for j in range(i + 1, m):
                if last_pos[unique[i]] < first_pos[unique[j]]:
                    result = max(result, 1 + compute(j))

            dp[i] = result
            return result

        max_chain = compute(0)
        results.append(str(m - max_chain))

    return '\n'.join(results)
