    n, m = map(int, lines[1].split())

    rules = []
    for i in range(m):
        rule_line = lines[2 + i]
        pos1, t1, pos2, t2 = rule_line.split()
        rules.append((int(pos1), t1, int(pos2), t2))

    s = lines[2 + m]

    # Map character to type (V or C)
    def get_type(char_idx):
        if vowel_cons_pattern[char_idx] == 'V':
            return 'V'
        return 'C'

    def is_vowel(char):
        return char in vowel_cons_pattern and get_type(char) == 'V'

    def is_consonant(char):
        return char in vowel_cons_pattern and get_type(char) == 'C'

    # For each position, get valid chars based on type
    def get_chars_for_type(position_type):
        chars = []
        used = set()
        for i in range(min(len(vowel_cons_pattern), n)):
            c = chr(97 + i)  # Start from 'a'
            if c not in used:
                used.add(c)
                t = get_type(i)
                if t == position_type:
                    chars.append(c)
