        if pos == n:
            return abs(bal) == k

        # Try W, L, D in order
        for choice in ['W', 'L', 'D']:
            # Determine the character
            char = result[pos] if result[pos] != '?' else choice

            if s[pos] != '?' and s[pos] != char:
                continue

            new_bal = bal
            if char == 'W':
                new_bal += 1
            elif char == 'L':
                new_bal -= 1

            # Check constraint
            if pos < n - 1 and abs(new_bal) >= k:
                continue

            if can_complete(pos + 1, new_bal):
                return True

        return False

    # Find a valid starting choice for position 0
    found = False
    def backtrack(pos, bal):
        nonlocal found
        if found:
            return

        if pos == n:
            if abs(bal) == k:
                found = True
                return True
            return False

        for choice in ['W', 'L', 'D']:
            char = result[pos] if result[pos] != '?' else choice

            if s[pos] != '?' and s[pos] != char:
                continue

            new_bal = bal
            if char == 'W':
                new_bal += 1
            elif char == 'L':
                new_bal -= 1

            if pos < n - 1 and abs(new_bal) >= k:
                continue

            if backtrack(pos + 1, new_bal):
                # Found a solution
                if current_bal != bal:
                    result[pos] = char
                    return True

        return False

    # Actually, better approach: use memoized search with path reconstruction
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp_search(pos, bal):
        if pos == n:
            return abs(bal) == k

        # Try W, L, D
        for choice in ['W', 'L', 'D']:
            char = result[pos] if result[pos] != '?' else choice
            if s[pos] != '?' and s[pos] != char:
                continue

            new_bal = bal
            if char == 'W':
                new_bal += 1
            elif char == 'L':
                new_bal -= 1

            if pos < n - 1 and abs(new_bal) >= k:
                continue

            if dp_search(pos + 1, new_bal):
                result[pos] = char
                return True

        return False

    reset_result = list(s)
    dp_search.cache_clear()
    dp_search(0, 0)

    return ''.join(reset_result) + '\n' if ''.join(reset_result) != s or s.count('?') > 0 else "NO\n"
