        dp = {1: 1}

        for v in tree[u]:
            if v == p:
                continue

            child_dp = dfs(v, u)
            new_dp = {}

            for s1, p1 in dp.items():
                # Option 1: Connect u-v (merge components)
                for s2, p2 in child_dp.items():
                    if s1 + s2 <= n:
                        new_val = p1 * p2
                        if s1 + s2 not in new_dp or new_dp[s1 + s2] < new_val:
                            new_dp[s1 + s2] = new_val

                # Option 2: Cut u-v (v's component closes with size s2)
                for s2, p2 in child_dp.items():
                    if s1 <= n:
                        new_val = p1 * p2 * s2
                        if s1 not in new_dp or new_dp[s1] < new_val:
                            new_dp[s1] = new_val

            dp = new_dp

        return dp

    result = dfs(1, 0)

    # At root, the component of size s is closed, contributing s to the product
    ans = 0
    for s, p in result.items():
        val = p * s
        if val > ans:
