            adj[v].append(u)

    def bfs_reachable(started_set, target):
        # BFS to count inactive cores reachable from target
        if target in started_set:
            return 0

        visited = {target}
        q = deque([target])
        count = 0

        while q:
            node = q.popleft()
            if node not in started_set:
                count += 1
            for neighbor in adj[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    q.append(neighbor)

        return count

    def simulate(kickstart):
        started = {kickstart}
        inactive = set(range(n)) - started
        total = 0

        # Initial activation
        total += len(inactive) + 1  # All nodes reachable initially

        for _ in range(n - 1):
            # Find all candidates: inactive cores with at least one started neighbor
            candidates = []
            for node in inactive:
                if any(neighbor in started for neighbor in adj[node]):
                    candidates.append(node)

            if not candidates:
                break

            # Greedy: choose candidate with highest potential
            best_candidate = max(candidates, key=lambda x: bfs_reachable(started, x))

            total += bfs_reachable(started, best_candidate)
            started.add(best_candidate)
            inactive.discard(best_candidate)

        return total

    best = 0
    for k in range(n):
        total = simulate(k)
        if total > best:
            best = total

    return str(best)
