def solution(input_str):
    """
    Solve the chessboard matching problem where we want to place pairs of chessmen
    with Manhattan distance exactly 3, maximizing the total number of chessmen.

    Args:
        input_str: String containing "n m" (number of rows and columns)

    Returns:
        String containing the maximum number of chessmen (as a string)
    """
    n, m = map(int, input_str.strip().split())

    # Handle 1D boards (1 x m or n x 1)
    if n == 1:
        # For 1xm, we can pair cells (i, i+3), (i+3, i+6), etc.
        # Maximum cells = 2 * floor((m - 1) / 2)
        return str(2 * (m - 1) // 2)

    if m == 1:
        # For nx1, symmetric case
        return str(2 * (n - 1) // 2)

    # Handle small 2D boards where distance 3 pairs are limited
    if n <= 2 and m <= 2:
        # 1x1: 0, 2x1: 0, 1x2: 0, 2x2: 0 (max distance is 2)
        return "0"

    # Handle boards with one dimension equal to 2
    if n == 2:
        # For 2xm, most pairs are within rows (distance 3 horizontally)
        # Horizontal pairs (i,j) and (i,j+3): can form (m-1)//3 pairs, but with overlaps
        # Actually, the pattern is 2*(m-1) // 2 for m >= 4
        if m < 4:
            return "0"
        return str(2 * (m - 1) // 2)

    if m == 2:
        # For n x 2, symmetric case
        if n < 4:
            return "0"
        return str(2 * (n - 1) // 2)

    # For larger boards (n,m >= 3), the answer is:
    # Total cells minus 1 if total is odd (due to bipartite coloring constraint)
    # Since pairs must be between different colors in checkerboard
    total_cells = n * m
    if total_cells % 2 == 1:
        return str(total_cells - 1)
    else:
        return str(total_cells)
